import os
import sys
import socket
import subprocess
import shlex
import signal

def get_config():
    return {
        "host": os.getenv("DIAG_HOST", "127.0.0.1"),
        "port": int(os.getenv("DIAG_PORT", "8080")),
        "timeout": int(os.getenv("DIAG_TIMEOUT", "5"))
    }

def validate_command(cmd):
    allowed_commands = ["ping", "ip", "hostname", "date", "whoami"]
    parts = shlex.split(cmd)
    if not parts:
        return False, "Empty command"
    if parts[0] not in allowed_commands:
        return False, f"Command '{parts[0]}' not allowed"
    for arg in parts[1:]:
        if any(c in arg for c in ";|&$`\\\"'"):
            return False, "Invalid characters in arguments"
    return True, "Valid"

def run_command(cmd, timeout):
    try:
        result = subprocess.run(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=timeout,
            shell=False
        )
        return result.stdout.decode(), result.stderr.decode(), result.returncode
    except subprocess.TimeoutExpired:
        return "", "Command timed out", -1
    except Exception as e:
        return "", str(e), -1

def server_mode(config):
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server_socket.bind((config["host"], config["port"]))
    server_socket.listen(1)
    server_socket.settimeout(config["timeout"])

    print(f"Server listening on {config['host']}:{config['port']}")

    try:
        conn, addr = server_socket.accept()
        print(f"Connection from {addr}")
        conn.settimeout(config["timeout"])

        while True:
            data = conn.recv(1024).decode().strip()
            if not data:
                break

            is_valid, msg = validate_command(data)
            if not is_valid:
                conn.sendall(f"Error: {msg}\n".encode())
                continue

            stdout, stderr, code = run_command(data.split(), config["timeout"])
            output = f"Return Code: {code}\nStdout: {stdout}\nStderr: {stderr}\n"
            conn.sendall(output.encode())

    except socket.timeout:
        print("Connection timed out")
    except Exception as e:
        print(f"Server error: {e}")
    finally:
        conn.close()
        server_socket.close()

def client_mode(config):
    client_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    client_socket.settimeout(config["timeout"])

    try:
        client_socket.connect((config["host"], config["port"]))
        print(f"Connected to {config['host']}:{config['port']}")

        while True:
            cmd = input("Enter command (or 'exit'): ").strip()
            if cmd.lower() == "exit":
                break

            client_socket.sendall(cmd.encode())
            response = client_socket.recv(4096).decode()
            print(response)

    except socket.timeout:
        print("Connection timed out")
    except Exception as e:
        print(f"Client error: {e}")
    finally:
        client_socket.close()

def main():
    config = get_config()
    if len(sys.argv) > 1 and sys.argv[1] == "client":
        client_mode(config)
    else:
        server_mode(config)

if __name__ == "__main__":
    main()
